import { useState } from 'react';
import { Menu, X, ChevronDown, User } from 'lucide-react';
import { Link } from 'react-router-dom';   // <-- IMPORTANT
import AuthModal from './AuthModal';

const Header = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const [authModalOpen, setAuthModalOpen] = useState(false);

  const handleAuthClick = () => {
    setAuthModalOpen(true);
  };

  return (
    <>
      <header className="bg-white shadow-lg sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">

            {/* Logo */}
            <div className="flex-shrink-0 flex items-center">
              <h1 className="text-2xl font-bold text-blue-600">Logo</h1>
            </div>

            {/* Navigation Desktop */}
            <nav className="hidden md:flex space-x-8">

              <Link to="/" className="text-gray-700 hover:text-blue-600 px-3 py-2 text-sm font-medium transition duration-300">
                Accueil
              </Link>

              <div className="relative">
                <button 
                  className="text-gray-700 hover:text-blue-600 px-3 py-2 text-sm font-medium flex items-center transition duration-300"
                  onMouseEnter={() => setDropdownOpen(true)}
                  onMouseLeave={() => setDropdownOpen(false)}
                >
                  Services
                  <ChevronDown className="ml-1 h-4 w-4" />
                </button>

                {dropdownOpen && (
                  <div 
                    className="absolute left-0 mt-2 w-48 bg-white rounded-md shadow-lg py-1 z-50"
                    onMouseEnter={() => setDropdownOpen(true)}
                    onMouseLeave={() => setDropdownOpen(false)}
                  >
                    <Link to="/services/web" className="block px-4 py-2 text-sm text-gray-700 hover:bg-blue-50 hover:text-blue-600">
                      Développement Web
                    </Link>
                    <Link to="/services/design" className="block px-4 py-2 text-sm text-gray-700 hover:bg-blue-50 hover:text-blue-600">
                      Design UI/UX
                    </Link>
                    <Link to="/services/seo" className="block px-4 py-2 text-sm text-gray-700 hover:bg-blue-50 hover:text-blue-600">
                      SEO
                    </Link>
                  </div>
                )}
              </div>

              <Link to="/portfolio" className="text-gray-700 hover:text-blue-600 px-3 py-2 text-sm font-medium transition duration-300">
                Portfolio
              </Link>

              <Link to="/about" className="text-gray-700 hover:text-blue-600 px-3 py-2 text-sm font-medium transition duration-300">
                À propos
              </Link>

              <Link to="/contact" className="text-gray-700 hover:text-blue-600 px-3 py-2 text-sm font-medium transition duration-300">
                Contact
              </Link>

            </nav>

            {/* CTA Button Desktop */}
            <div className="hidden md:flex items-center space-x-4">
              <button 
                onClick={handleAuthClick}
                className="bg-blue-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-blue-700 transition duration-300 shadow-md flex items-center"
              >
                <User className="h-4 w-4 mr-2" />
                Connexion
              </button>
            </div>

            {/* Mobile menu button */}
            <div className="md:hidden">
              <button
                onClick={() => setIsOpen(!isOpen)}
                className="text-gray-700 hover:text-blue-600 focus:outline-none"
              >
                {isOpen ? <X className="h-6 w-6" /> : <Menu className="h-6 w-6" />}
              </button>
            </div>
          </div>

          {/* Mobile Navigation */}
          {isOpen && (
            <div className="md:hidden">
              <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3 bg-white border-t">

                <Link to="/" className="text-gray-700 hover:text-blue-600 block px-3 py-2 text-base font-medium">
                  Accueil
                </Link>

                <Link to="/services" className="text-gray-700 hover:text-blue-600 block px-3 py-2 text-base font-medium">
                  Services
                </Link>

                <Link to="/portfolio" className="text-gray-700 hover:text-blue-600 block px-3 py-2 text-base font-medium">
                  Portfolio
                </Link>

                <Link to="/about" className="text-gray-700 hover:text-blue-600 block px-3 py-2 text-base font-medium">
                  À propos
                </Link>

                <Link to="/contact" className="text-gray-700 hover:text-blue-600 block px-3 py-2 text-base font-medium">
                  Contact
                </Link>

                <button 
                  onClick={handleAuthClick}
                  className="w-full bg-blue-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-blue-700 transition duration-300 mt-4 flex items-center justify-center"
                >
                  <User className="h-4 w-4 mr-2" />
                  Connexion
                </button>
              </div>
            </div>
          )}
        </div>
      </header>

      {/* Modal d'authentification */}
      <AuthModal 
        isOpen={authModalOpen} 
        onClose={() => setAuthModalOpen(false)} 
      />
    </>
  );
};

export default Header;
